/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METSalesOrderLineService extends SysOperationServiceBase
{
    #OCCRetryCount
    
}

Method.Source:
    /// <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="salesOrderLineRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderResponseContract</c>
    /// </returns>
    public METSalesOrderLineResponseContract cancelSalesOrderLine(METSalesOrderLineRequestContract salesOrderLineRequest)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated";

        [result, message] = this.processCancelSalesOrderLine(salesOrderLineRequest);
        
        return METSalesOrderLineResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// cancels the sales order line
    /// </summary>
    /// <param name="_salesOrderLineRequest">The contract instance</param>
    /// <returns>Container of Results</returns>
    public container processCancelSalesOrderLine(METSalesOrderLineRequestContract _salesOrderLineRequest)
    {
        METProcessingStatus Result;
        Description255      Message;
        SalesLine           salesLine;
        SalesId             salesId;
        LineNum             lineNum;
        DataAreaId          dataAreaId;

        salesId     = _salesOrderLineRequest.parmSalesId();
        lineNum     = _salesOrderLineRequest.parmLineNum();
        dataAreaId  = _salesOrderLineRequest.parmDataAreaId();
        
        try
        {
            ttsbegin;

            changecompany(dataAreaId)
            {
                salesLine = SalesLine::find(salesId, lineNum, true);
        
                if(!salesLine.RecId)
                {
                    Result = METProcessingStatus::Error;
                    Message = "@MET:SalesOrderLineNotFound";
                }
                else if(salesLine.SalesStatus != SalesStatus::Backorder)
                {
                    Result = METProcessingStatus::Error;
                    Message = "@MET:SalesOrderLineNotOpen";
                }
                else
                {
                    //code copied from FormSalesUpdateRemain.CloseOk()
                
                    MCRSalesOrderCancellation mcrSalesOrderCancellation;

                    if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                    {
                        mcrSalesOrderCancellation = new MCRSalesOrderCancellation();
                        mcrSalesOrderCancellation.preCancel(SalesTable::find(salesLine.SalesId));
                    }

                    SalesUpdateRemain salesUpdateRemain = SalesUpdateRemain::construct();
                    boolean updated = salesUpdateRemain.updateDeliverRemainder(salesLine, 0, 0);

                    if (updated)
                    {
                        if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                        {
                            SalesTable salesTable;
                    
                            if (salesLine.SalesStatus == SalesStatus::Canceled)
                            {
                                SalesLine salesLineLocal = SalesLine::findRecId(salesLine.RecId);
                                mcrSalesOrderCancellation.postCancelLine(salesLineLocal);
                                
                                // Additional find in case the status changed in the postCancelLine method
                                salesTable = SalesTable::find(salesLine.SalesId,true);

                                if (salesTable.SalesStatus == SalesStatus::Canceled)
                                {
                                    mcrSalesOrderCancellation.postCancelOrder(salesTable);
                                }
                            }

                            // Additional find in case the status changed in the postCancelLine or postCancelOrder method
                            salesTable = SalesTable::find(salesLine.SalesId, true);
                            
                            // If sales order is paid by loyalty create the refund loyalty lines and post them as part of this process
                            if (salesTable.SalesStatus != SalesStatus::Canceled)
                            {
                                mcrSalesOrderCancellation.RefundLoyaltyPointsForSalesLine(salesTable, salesLine);
                            }
                            
                            mcrSalesOrderCancellation.postCancelAdjPayment(salesTable);
                        }

                        Result = METProcessingStatus::Success;
                        Message = "@MET:SalesOrderLineUpdateSuccessful";
                    }
                    else
                    {
                        Result = METProcessingStatus::Error;
                        Message = "@MET:SalesOrderLineUpdateFailed";
                    }
                }
                   
                if(Result == METProcessingStatus::Error)
                {
                    throw error(Message);
                }
                
                ttscommit;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesOrderUpdateFailedDatabaseDeadlock");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesOrderUpdateFailedDatabaseDeadlock");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesOrderUpdateFailedDatabaseConflict");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {                            
                    retry;
                }
            }
            else
            {
                error("@MET:SalesOrderUpdateFailedDatabaseConflict");
                throw Exception::UpdateConflict;
            }
        }
        
        return [Result, Message];
       
    }
